import React from 'react';
import SectionHeading from './SectionHeading';
import Reveal from './Reveal';
import Icon from './icons';
import { skillGroups } from '../data/content';

export default function Skills() {
  return (
    <section id="skills" className="py-20 px-4 sm:px-6">
      <div className="max-w-6xl mx-auto">
        <Reveal>
          <SectionHeading eyebrow="// skills" heading="Toolbox" />
        </Reveal>

        <div className="mt-8 grid sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {skillGroups.map((group, idx) => (
            <Reveal key={group.title} delay={(idx % 3) * 80}>
              <div className="h-full rounded-2xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-6 transition-transform hover:-translate-y-1 hover:shadow-md">
                <div className="inline-flex items-center justify-center w-9 h-9 rounded-lg bg-indigo-500/10 text-indigo-500 dark:text-indigo-400 mb-3">
                  <Icon name={group.icon} size={18} />
                </div>
                <h3 className="font-display font-semibold text-zinc-900 dark:text-zinc-50">{group.title}</h3>
                <div className="mt-3 flex flex-wrap gap-1.5">
                  {group.items.map((item) => (
                    <span
                      key={item}
                      className="px-2.5 py-1 rounded-full text-xs font-mono border border-zinc-200 dark:border-zinc-800 text-zinc-600 dark:text-zinc-400"
                    >
                      {item}
                    </span>
                  ))}
                </div>
              </div>
            </Reveal>
          ))}
        </div>
      </div>
    </section>
  );
}
